"""RibbonPlan: pure calculations for ordered colored material bands."""


def _validate_bands(bands):
    if type(bands) is not list or len(bands) > 1000:
        raise ValueError("invalid bands")
    for band in bands:
        if type(band) is not dict or set(band) != {"color", "length"}:
            raise ValueError("invalid band record")
        if type(band["color"]) is not str or not band["color"]:
            raise ValueError("invalid color")
        if type(band["length"]) is not int or not 1 <= band["length"] <= 1000000:
            raise ValueError("invalid length")


def tile(bands, count):
    _validate_bands(bands)
    if type(count) is not int or not 0 <= count <= 1000:
        raise ValueError("invalid count")
    result = []
    for band in bands:
        for _ in range(count):
            result.append({"color": band["color"], "length": band["length"]})
    return result
